package com.crowdin.client.core.http.impl.json;

import org.junit.Test;
import static org.junit.Assert.*;

public class JacksonJsonTransformerTest {

    @Test
    public void parseProjectJson() {
        // Arrange
        String json = "{\"id\":\"12345\",\"name\":\"Example Project\"}";
        Class<Project> clazz = Project.class;

        // Act
        Object result = new JacksonJsonTransformer().parse(json, clazz);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof Project);
    }

    @Test
    public void parseExportOptionsJson() {
        // Arrange
        String json = "{\"options\":{\"language\":\"en\"}}";
        Class<ExportOptions> clazz = ExportOptions.class;

        // Act
        Object result = new JacksonJsonTransformer().parse(json, clazz);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof ExportOptions);
    }

    @Test
    public void parseLanguageTranslationsJson() {
        // Arrange
        String json = "{\"en\":{\"key1\":\"value1\"}}";
        Class<LanguageTranslations> clazz = LanguageTranslations.class;

        // Act
        Object result = new JacksonJsonTransformer().parse(json, clazz);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof LanguageTranslations);
    }

    @Test
    public void parseFileInfoJson() {
        // Arrange
        String json = "{\"fileName\":\"example.txt\",\"content\":\"Hello World\"}";
        Class<FileInfo> clazz = FileInfo.class;

        // Act
        Object result = new JacksonJsonTransformer().parse(json, clazz);

        // Assert
        assertNotNull(result);
        assertTrue(result instanceof FileInfo);
    }

    @Test
    public void convertProject() {
        // Arrange
        Project project = new Project();
        project.setId("12345");
        project.setName("Example Project");

        // Act
        String result = new JacksonJsonTransformer().convert(project);

        // Assert
        assertNotNull(result);
        assertTrue(result.contains("\"id\":\"12345\""));
    }

    @Test
    public void convertLanguageTranslations() {
        // Arrange
        LanguageTranslations translations = new LanguageTranslations();
        translations.setEn(new Translation("key1", "value1"));

        // Act
        String result = new JacksonJsonTransformer().convert(translations);

        // Assert
        assertNotNull(result);
        assertTrue(result.contains("\"en\":{\"key1\":\"value1\"}}"));
    }

    @Test
    public void convertFileInfo() {
        // Arrange
        FileInfo fileInfo = new FileInfo();
        fileInfo.setFileName("example.txt");
        fileInfo.setContent("Hello World");

